import{_ as t}from"./chunks/onnx-export.i-QhCQcz.js";import{_ as o,o as r,c as n,a0 as i}from"./chunks/framework.Ckbw5VQO.js";const g=JSON.parse('{"title":"ONNX","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models/onnx.md","filePath":"guide/models/onnx.md"}'),s={name:"guide/models/onnx.md"};function a(l,e,c,h,d,m){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="onnx" tabindex="-1"><a href="https://onnx.ai/" target="_blank" rel="noreferrer">ONNX</a> <a class="header-anchor" href="#onnx" aria-label="Permalink to &quot;[ONNX](https://onnx.ai/)&quot;">​</a></h1><p>In geo-ml, once the YOLOv8 model has been fine-tuned on our pools &amp; buildings, it needs to run <strong>in the browser</strong> - no server, no Python, no GPU. That is where ONNX comes in: we export the trained weights into a universal format (<code>.onnx</code>) that the browser loads and executes directly via <strong><a href="https://onnxruntime.ai/docs/tutorials/web/" target="_blank" rel="noreferrer">ONNX Runtime Web</a></strong>. All inference computation runs entirely client-side, on the user&#39;s machine.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>ONNX</strong> (<em>Open Neural Network Exchange</em>) is a <strong>universal file format</strong> for machine-learning models. It lets you train a model in one library (here <a href="https://docs.pytorch.org/docs/2.12/onnx.html" target="_blank" rel="noreferrer">PyTorch</a> / <a href="https://docs.ultralytics.com/integrations/onnx" target="_blank" rel="noreferrer">Ultralytics</a>) and run it <strong>elsewhere</strong> - including in a web browser, with no server.</p></div><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>A trained model is tied to its framework: a PyTorch <code>.pt</code> needs PyTorch to run. And PyTorch does not run in a browser.</p><p>ONNX decouples the <strong>model</strong> from the <strong>training library</strong> by serialising the compute graph and weights into a portable file.</p><div class="tip custom-block"><p class="custom-block-title">Compute graph &amp; weights</p><ul><li><strong>Compute graph</strong>: the model&#39;s <em>recipe</em> - the ordered list of operations (convolutions, normalisations, activations…) and how they chain together. This is the network architecture.</li><li><strong>Weights</strong>: the <em>numerical values</em> learned during training - millions of numbers that, combined with the graph, produce the detections. Without the weights, the graph is an empty shell.</li></ul></div><img src="'+t+'" style="display:block;margin:1.5rem auto;width:100%;height:auto;"><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Any compatible ONNX runtime can load this file and execute it.</p></div><h2 id="onnx-runtime-web" tabindex="-1"><a href="https://onnxruntime.ai/docs/tutorials/web/" target="_blank" rel="noreferrer">ONNX Runtime Web</a> <a class="header-anchor" href="#onnx-runtime-web" aria-label="Permalink to &quot;[ONNX Runtime Web](https://onnxruntime.ai/docs/tutorials/web/)&quot;">​</a></h2><p>The project is deployed <strong>without a backend</strong> (GitHub Pages), so inference must run client-side. That is the role of <strong>ONNX Runtime Web</strong>:</p><div class="tip custom-block"><p class="custom-block-title">Inference</p><p><strong>Inference</strong> is the step where the model <em>uses</em> what it has learned: we give it an image, it returns predictions (boxes, classes, scores). It is the opposite of training - here we no longer modify the weights, we apply them.</p></div><ul><li>it loads the <code>.onnx</code> directly into the page</li><li>it executes it in <strong><a href="https://webassembly.org/" target="_blank" rel="noreferrer">WebAssembly (WASM)</a></strong> - near-native code in the browser</li></ul><div class="tip custom-block"><p class="custom-block-title">WebAssembly (WASM)</p><p>A binary format executable by all modern browsers, designed to run at near-native speed. It allows C++/Rust code (here the ONNX engine) to run in a browser tab, with no plugin or installation required.</p></div>',14)])])}const b=o(s,[["render",a]]);export{g as __pageData,b as default};
